+fn deduplicate_predicates(mut predicates: Vec<Scalar>, _: &LogicalPlan) -> Result<Vec<Scalar>> {
+    let mut retained = 0;
+    for index in 0..predicates.len() {
+        if !predicates[..retained].contains(&predicates[index]) {
+            predicates.swap(retained, index);
+            retained += 1;
+        }
+    }
+    predicates.truncate(retained);
+    Ok(predicates)
+}
